-- Areas of interest: only detections inside one (plus a buffer) open incidents.
-- Generated by tools/build_area_migration.ps1; edit the template, not the output.

CREATE TABLE areas_of_interest (
    code       text PRIMARY KEY,
    name       text NOT NULL,
    boundary   geometry(MultiPolygon, 4326) NOT NULL,
    -- Keeps coastal pixels (a VIIRS pixel is ~375 m) and fires right on the border.
    buffer_m   double precision NOT NULL CHECK (buffer_m >= 0),
    source     text NOT NULL
);

-- The buffered boundary cut into small pieces: ST_Intersects against a GIST index of
-- simple polygons is much faster than against one large multipolygon.
CREATE TABLE area_of_interest_parts (
    id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    area_code  text NOT NULL REFERENCES areas_of_interest (code) ON DELETE CASCADE,
    geom       geometry(Geometry, 4326) NOT NULL
);

CREATE INDEX ix_area_of_interest_parts_geom ON area_of_interest_parts USING gist (geom);

ALTER TABLE fire_detections ADD COLUMN area_code text REFERENCES areas_of_interest (code);

-- Greece: Natural Earth 1:10m admin-0 countries, Greek point of view (public domain),
-- coordinates rounded to 4 decimals by tools/extract_greece.py.
INSERT INTO areas_of_interest (code, name, boundary, buffer_m, source)
VALUES (
    'GRC',
    'Greece',
    ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON('{{GREECE_GEOJSON}}'), 4326)), 3)),
    2000,
    'Natural Earth 1:10m admin-0 countries, Greek point of view (ne_10m_admin_0_countries_grc)');

-- Buffer in EPSG:2100 (Greek Grid) so the distance is in metres.
INSERT INTO area_of_interest_parts (area_code, geom)
SELECT code, ST_Subdivide(ST_Transform(ST_Buffer(ST_Transform(boundary, 2100), buffer_m), 4326), 256)
FROM areas_of_interest;

-- Detections stored before this migration.
UPDATE fire_detections d
SET area_code = p.area_code
FROM area_of_interest_parts p
WHERE ST_Intersects(p.geom, d.location);
